class TestConfigStructure:
    """Validate the static shape of the exported configuration."""

    def test_config_is_object(self, babel_config):
        assert isinstance(babel_config, dict), (
            f"Expected config to be an object, got {type(babel_config).__name__}"
        )

    def test_has_presets_key(self, babel_config):
        assert "presets" in babel_config, "Config must contain a 'presets' array."

    def test_presets_is_list(self, babel_config):
        assert isinstance(babel_config["presets"], list), "'presets' must be an array."

    def test_presets_not_empty(self, babel_config):
        assert len(babel_config["presets"]) > 0, "'presets' array must not be empty."

    def test_preset_names_are_strings(self, babel_config):
        for preset in babel_config["presets"]:
            # Preset can be a string or a tuple [name, options]
            if isinstance(preset, list):
                assert len(preset) == 2, f"Preset tuple must have exactly 2 elements: {preset}"
                name, options = preset
                assert isinstance(name, str), f"Preset name must be a string: {name}"
                assert isinstance(options, dict), f"Preset options must be a dict: {options}"
            else:
                assert isinstance(preset, str), f"Preset must be a string or tuple: {preset}"

    def test_expected_presets_present(self, babel_config):
        """Ensure the exact presets from the spec are configured."""
        preset_names = []
        for preset in babel_config["presets"]:
            if isinstance(preset, list):
                preset_names.append(preset[0])
            else:
                preset_names.append(preset)

        assert "@babel/preset-env" in preset_names, "Missing @babel/preset-env"
        assert "@babel/preset-react" in preset_names, "Missing @babel/preset-react"

    def test_preset_env_targets(self, babel_config):
        """Validate the 'targets' option for preset-env."""
        for preset in babel_config["presets"]:
            if isinstance(preset, list) and preset[0] == "@babel/preset-env":
                options = preset[1]
                assert "targets" in options, "preset-env must specify 'targets'"
                assert options["targets"] == {"node": "current"}, (
                    f"Expected targets {{'node': 'current'}}, got {options['targets']}"
                )
                return
        pytest.fail("preset-env not found in config")

    def test_preset_react_runtime(self, babel_config):
        """Validate the 'runtime' option for preset-react."""
        for preset in babel_config["presets"]:
            if isinstance(preset, list) and preset[0] == "@babel/preset-react":
                options = preset[1]
                assert "runtime" in options, "preset-react must specify 'runtime'"
                assert options["runtime"] == "automatic", (
                    f"Expected runtime 'automatic', got {options['runtime']}"
                )
                return
        pytest.fail("preset-react not found in config")


