class TestBabelTransformation:
    """Validate the config actually transpiles code correctly."""

    @pytest.mark.parametrize(
        "source_code, expected_substring",
        [
            # Modern JS: optional chaining
            ("const x = obj?.prop ?? 'default';", "??"),
            # JSX: should be transformed to React.createElement or jsx runtime
            ("const el = <div className='test'>Hello</div>;", "jsx"),
            # Arrow functions
            ("const add = (a, b) => a + b;", "=>"),
            # Template literals
            ("const msg = `Hello ${name}`;", "Hello"),
        ],
        ids=["optional-chaining", "jsx", "arrow-fn", "template-literal"],
    )
    def test_transpiles_modern_syntax(self, babel_core, source_code, expected_substring):
        """Ensure the config can transform representative modern syntax."""
        try:
            result = babel_core.transformSync(source_code, {
                "configFile": CONFIG_PATH,
                "filename": "test.js",
            })
        except Exception as exc:
            pytest.fail(f"Babel transformation failed: {exc}")

        assert result.code is not None, "Transformation produced no output."
        assert expected_substring in result.code, (
            f"Expected '{expected_substring}' in output, got:\n{result.code}"
        )

    def test_jsx_automatic_runtime(self, babel_core):
        """
        Verify that JSX uses the automatic runtime (no React import needed).

        The output should reference 'jsx' or 'jsxs' from 'react/jsx-runtime'.
        """
        source = "const el = <div>Hello</div>;"
        result = babel_core.transformSync(source, {
            "configFile": CONFIG_PATH,
            "filename": "test.jsx",
        })

        assert "react/jsx-runtime" in result.code, (
            f"Expected automatic JSX runtime import, got:\n{result.code}"
        )

    def test_preset_env_targets_node_current(self, babel_core):
        """
        With target 'node: current', modern syntax should be preserved
        (not downleveled to ES5). For example, arrow functions should remain.
        """
        source = "const f = () => 42;"
        result = babel_core.transformSync(source, {
            "configFile": CONFIG_PATH,
            "filename": "test.js",
        })

        assert "=>" in result.code, (
            f"Arrow function should be preserved for current Node, got:\n{result.code}"
        )

    def test_invalid_syntax_raises_error(self, babel_core):
        """Invalid JavaScript should raise a Babel error, not silently pass."""
        source = "const = ;"
        with pytest.raises(Exception) as exc_info:
            babel_core.transformSync(source, {
                "configFile": CONFIG_PATH,
                "filename": "broken.js",
            })
        assert "SyntaxError" in str(exc_info.type) or "ParseError" in str(exc_info.type), (
            f"Expected a syntax error, got {exc_info.type.__name__}"
        )

    def test_empty_input_returns_empty_output(self, babel_core):
        """Empty source should produce empty (or whitespace-only) output."""
        result = babel_core.transformSync("", {
            "configFile": CONFIG_PATH,
            "filename": "empty.js",
        })
        assert result.code.strip() == "", f"Expected empty output, got: {result.code!r}"


