class TestPerformance:
    """Ensure transformation latency is within acceptable bounds."""

    def test_transformation_speed(self, babel_core):
        """
        A simple transformation should complete in under 2 seconds.
        This is a sanity check to catch pathological config issues.
        """
        source = "const x = <div>{[1,2,3].map(i => <span key={i}>{i}</span>)}</div>;"
        start = time.perf_counter()
        babel_core.transformSync(source, {
            "configFile": CONFIG_PATH,
            "filename": "perf.jsx",
        })
        elapsed = time.perf_counter() - start
        assert elapsed < 2.0, f"Transformation took {elapsed:.2f}s, exceeding 2s threshold."


