class TestConfigIntegrity:
    """Validate the config file itself is well-formed and consistent."""

    def test_config_file_syntax(self):
        """The file should be valid JavaScript (CommonJS)."""
        with open(CONFIG_PATH, "r", encoding="utf-8") as f:
            content = f.read()

        # Basic sanity: should contain module.exports
        assert "module.exports" in content, "Config must use module.exports"

        # Should be parseable by Node (already tested in fixture, but double-check)
        assert content.count("(") == content.count(")"), "Unbalanced parentheses in config"

    def test_config_has_no_comments_in_json_output(self, babel_config):
        """The loaded config should not contain any comment keys."""
        assert not any(key.startswith("_") for key in babel_config.keys()), (
            "Config should not contain private/comment keys"
        )

    def test_config_is_deterministic(self):
        """Loading the config twice should yield identical results."""
        import subprocess

        node_script = (
            "const config = require('./babel.config.js'); "
            "process.stdout.write(JSON.stringify(config));"
        )
        outputs = []
        for _ in range(2):
            result = subprocess.run(
                ["node", "-e", node_script],
                cwd=os.path.dirname(CONFIG_PATH),
                capture_output=True,
                text=True,
                check=True,
                timeout=10,
            )
            outputs.append(result.stdout)

        assert outputs[0] == outputs[1], "Config loading is non-deterministic."


