class TestEdgeCases:
    """Test the config against unusual but valid inputs."""

    def test_jsx_with_fragment(self, babel_core):
        """JSX fragments should be supported."""
        source = "const el = <><div>1</div><div>2</div></>;"
        result = babel_core.transformSync(source, {
            "configFile": CONFIG_PATH,
            "filename": "fragment.jsx",
        })
        assert result.code is not None
        assert "Fragment" in result.code or "jsx" in result.code

    def test_typescript_syntax_not_required(self, babel_core):
        """
        Since no TypeScript preset is configured, TS syntax should fail.
        This confirms the config does NOT unexpectedly include TS support.
        """
        source = "const x: number = 42;"
        with pytest.raises(Exception):
            babel_core.transformSync(source, {
                "configFile": CONFIG_PATH,
                "filename": "test.ts",
            })

    def test_config_works_with_absolute_path(self, babel_core):
        """The config should work when referenced by absolute path."""
        abs_path = os.path.abspath(CONFIG_PATH)
        source = "const x = 1;"
        result = babel_core.transformSync(source, {
            "configFile": abs_path,
            "filename": "abs.js",
        })
        assert result.code is not None

    def test_config_handles_unicode(self, babel_core):
        """Unicode strings should pass through correctly."""
        source = "const greeting = 'héllo wörld 你好';"
        result = babel_core.transformSync(source, {
            "configFile": CONFIG_PATH,
            "filename": "unicode.js",
        })
        assert "héllo wörld 你好" in result.code


